INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('b9e2cbe7-599e-494d-9b3c-664711b7a273', '1984 (edición definitiva avalada por The Orwell Estate)', '24fa4d96-0914-4806-abe0-02d8bec4b6d8', 'https://books.google.com/books/content?id=uFI8Kmx3a0oC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '«No creo que la sociedad que he descrito en 1984 necesariamente llegue a ser una realidad, pero sí creo que puede llegar a existir algo parecido», escribía Orwell después de publicar su novela. Corría el año 1948, y la realidad se ha encargado de convertir esa pieza -entonces de ciencia ficción- en un manifiesto de la realidad. UNO DE LOS 5 LIBROS MÁS IMPORTANTES DE LOS ÚLTIMOS 125 AÑOS SEGÚN THE NEW YORK TIMES «Está entre mis libros favoritos, lo leo una y otra vez». Margaret Atwood En el año 1984 Londres es una ciudad lúgubre en la que la Policía del Pensamiento controla de forma asfixiante la vida de los ciudadanos. Winston Smith es un peón de este engranaje perverso y su cometido es reescribir la historia para adaptarla a lo que el Partido considera la versión oficial de los hechos. Hasta que decide replantearse la verdad del sistema que los gobierna y somete. La presente edición, avalada por The Orwell Estate, sigue fielmente el texto definitivo de las obras completas del autor, fijado por el profesor Peter Davison. Incluye un epílogo del novelista Thomas Pynchon, que aporta al análisis del libro su personal visión de los totalitarismos y la paranoia en el mundo moderno. Miguel Temprano García firma la soberbia traducción, que es la más reciente de la obra. La crítica ha dicho... «Aquí ya no estamos solo ante lo que habitualmente reconocemos como "literatura" e identificamos con la buena escritura. Aquí estamos, repito, ante energía visionaria. Y no todas las visiones se refieren al futuro, o al Más Allá.» Umberto Eco «No es difícil pensar que Orwell, en 1984, estuviera imaginando un futuro para la generación de su hijo, un mundo del que deseaba prevenirle.» Thomas Pynchon «La libertad es una obligación tan dolorosa que siempre habrá quien prefiera rendirse. La virtud de libros como 1984 es su capacidad para recordarnos que la libertad de los seres humanos responsables no es igual a la de los animales.» Anthony Burgess «Desde El proceso de Kafka ninguna obra fantástica ha alcanzado el horror lógico de 1984.» Arthur Koestler «Un libro magnífico y profundamente interesante.» Aldous Huxley «Orwell desarrolló la prosa inglesa más clara y atractiva del siglo XX. Pero es obvio que era mucho más que un gran escritor. Hoy resulta necesario debido a su pasión por la verdad.» The Sunday Times «Casi antes que nadie él comprendió que la corrupción de las palabras es un síntoma y a la vez la causa de la corrupción del pensamiento.» Antonio Muñoz Molina «Un intelectual radicalmente independiente cuya obra es de una claridad moral insobornable.» Guillermo Altares, El País «Probablemente el más influyente escritor occidental del siglo XX. [...] El verdadero Orwell, quienquiera que sea, sigue tomando forma.» The Times «Orwell fue la fuerza moral de su época.» Spectator', '9788490325070', 389, '2013-03-07', NULL, '2026-02-10T10:50:21.459392+00:00', 'es', 'DEBOLS!LLO') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('fb6fdcbf-33f1-4061-a99e-1bfaa6c90c0c', 'Ensayo sobre la ceguera', '847f63c9-dfa2-482f-8eeb-f39347598d4d', 'https://books.google.com/books/content?id=tKjAj5rDY0sC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', '2022: AÑO SARAMAGO Una novela y un autor que nos alertan sobre «la responsabilidad de tener ojos cuando otros los perdieron». «Dentro de nosotros hay algo que no tiene nombre, esa cosa es lo que somos». Un hombre parado ante un semáforo en rojo se queda ciego súbitamente. Es el primer caso de una «ceguera blanca» que se expande de manera fulminante. Internados en cuarentena o perdidos en la ciudad, los ciegos tendrán que enfrentarse con lo más primitivo en la naturaleza humana: la voluntad de sobrevivir a cualquier precio. Ensayo sobre la ceguera es la ficción de un autor que nos alerta sobre «la responsabilidad de tener ojos cuando otros los perdieron». José Saramago traza en este libro una imagen aterradora y conmovedora de los tiempos que estamos viviendo. En un mundo así, ¿cabrá alguna esperanza? El lector conocerá una experiencia imaginativa única. En un punto donde se cruzan literatura y sabiduría, José Saramago nos obliga a parar, cerrar los ojos y ver. Recuperar la lucidez y rescatar el afecto son dos propuestas fundamentales de una novela que es, también, una reflexión sobre la ética del amor y la solidaridad. La crítica ha dicho: «Una metáfora que, cuando se publicó, lo mismo podía valer para el sida que para el abandono de los mayores. En esta novela, la ceguera llega sin avisar y produce un deslumbramiento blanco permanente. De nuevo, desfilan lo mejor y lo peor de la especie. Como en las guerras». Tereixa Constenla, El País «Saramago siempre ha demostrado una imaginación audaz como novelista. Ésta es su obra más sorprendente e inquietante». Harold Bloom «No hay cinismo ni moraleja, sólo un reconocimiento lúcido y compasivo de las cosas tal como son, una cualidad que sólo puede calificarse honestamente como sabiduría». The New York Times «Hay novelas, como ésta, que después de leídas continuarán iluminando túneles en la conciencia, abriendo puertas de habitaciones a las que no nos habíamos asomado pese a estar dentro de nosotros». Juan José Millás «Saramago vuelve comprensible una realidad huidiza, con parábolas sostenidas por la imaginación, la compasión y la ironía». Comité Nobel «Un hombre con una sensibilidad y una capacidad de ver y de entender que están muy por encima de lo que en general vemos y entendemos los comunes mortales». Héctor Abad Faciolince «Saramago es un ejemplo, un estilo dignísimo de vida y literatura, que demuestra la posibilidad de navegar a contracorriente [...]. Su palabra tiene el valor de un anticongelante, de un remedio personal contra los vendavales de cinismo que nos envuelven». Luis García Montero «Yo no sé, ni quiero saberlo, de dónde ha sacado Saramago ese diabólico tono narrativo, duro y piadoso a un tiempo, [...] que le permite contar tan cerca del corazón y a la vez tan cerca de la historia». Luis Landero «Saramago escribe novelas sobre los mitos para desmitificarlos, [...] siempre para abordar la realidad que le rodea, para tratar de los problemas actuales que son de todos, y para que todo quede claro desde el principio». Rafael Conte, Babelia «Como Günter Grass o Cees Nooteboom, Saramago aspira a enlazar con un público que desborde límites nacionales». El País', '9788420498799', 270, '2010-07-15', NULL, '2026-02-10T10:52:15.545453+00:00', 'es', 'ALFAGUARA') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('2f88faf9-1f1c-4205-9e78-932d2375559e', 'Pack George Orwell (contiene: 1984 | Rebelión en la granja)', '24fa4d96-0914-4806-abe0-02d8bec4b6d8', 'https://books.google.com/books/publisher/content?id=wwbtDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&imgtk=AFLRE72cjB8OOGzPdhvWzoejQgw2bGQTWY6GYolu_oNHQgBFzDp9d3GMoOsB_-6FG1bYpN2R2XwJbdXd2-R7JDQsz6uCu2mL2z0xzTXBtKsIQNFnU8yrstSKjklJHry6rYhQjye3YogC&source=gbs_api', '<p> <b>Los dos clásicos distópicos de George Orwell reunidos en una edición estuche.</b> </p> <p> <b> <i>1984</i> </b> </p> <p> <b>«No creo que la sociedad que he descrito en </b> <i> <b>1984 </b> </i> <b>necesariamente llegue a ser una realidad, pero sí creo que puede llegar a existir algo parecido», escribía Orwell después de publicar su novela.</b> Corría el año 1948, y la realidad se ha encargado de convertir esa pieza -entonces de ciencia ficción- en un manifiesto de la realidad.</p> <p>En el año 1984 Londres es una ciudad lúgubre en la que la Policía del Pensamiento controla de forma asfixiante la vida de los ciudadanos. Winston Smith es un peón de este engranaje perverso y su cometido es reescribir la historia para adaptarla a lo que el Partido considera la versión oficial de los hechos. Hasta que decide replantearse la verdad del sistema que los gobierna y somete.</p> <p>_________________</p> <p> <b> <i>Rebelión en la granja</i> </b> </p> <p> <b>Un rotundo alegato a favor de la libertad y en contra del totalitarismo que se ha convertido en un clásico de la literatura del siglo XX.</b> </p> <p>Esta sátira de la Revolución rusa y el triunfo del estalinismo, escrita en 1945, se ha convertido por derechos propio en un hito de la cultura contemporánea y en uno de los libros más mordaces de todos los tiempos. Ante el auge de los animales de la Granja Solariega, pronto detectamos las semillas de totalitarismo en una organización aparentemente ideal; y en nuestros líderes más carismáticos, la sombra de los opresores más crueles.</p> <p> <b>Sobre las obras:</b> <br> <b>1984</b> <br> «Aquí ya no estamos solo ante lo que habitualmente reconocemos como "literatura" e identificamos con la buena escritura. Aquí estamos, repito, ante energía visionaria.»</p> <p>Umberto Eco</p> <p>«1984 está entre mis libros favoritos, lo leo una y otra vez.» <br> Margaret Atwood</p> <p>«No es difícil pensar que Orwell, en 1984, estuviera imaginando un futuro para la generación de su hijo, un mundo del que deseaba prevenirle.» <br> Thomas Pynchon</p> <p>«La libertad es una obligación tan dolorosa que siempre habrá quien prefiera rendirse. La virtud de libros como 1984 es su capacidad para recordarnos que la libertad de los seres humanos responsables no es igual a la de los animales.» <br> Anthony Burgess</p> <p>«Un libro magnífico y profundamente interesante.» <br> Aldous Huxley</p> <p> <b>Rebelión en la granja</b> <br> «Una obra literaria perfecta.» <br> T.S. Elliot</p> <p>«El libro que todo el mundo, toda la gente de a pie, debería leer. No ha perdido un ápice de lucidez en cincuenta años.» <br> Ruth Rendell</p> <p>«Casi antes que nadie él comprendió que la corrupción de las palabras es un síntoma y a la vez la causa de la corrupción del pensamiento.» <br> Antonio Muñoz Molina</p> <p>«Desde Los viajes de Gulliver no se ha escrito una parábola tan profunda, mordiente y satírica como Rebelión en la granja.» <br> Arthur Koestler</p>', '9788466355742', 496, '2020-07-02', NULL, '2026-02-10T10:59:22.224606+00:00', 'es', 'DEBOLS!LLO') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('b391c697-b03e-4e18-a96e-54ef12e31815', 'Cien años de soledad', '678b3020-67e2-45aa-8b0e-7fc838987c04', 'https://images.isbndb.com/covers/2673183482375.jpg', '<b>En ocasión del 50 aniversario de la publicación de<i> Cien años de soledad</i>, llega una edición con ilustraciones inéditas de la artista chilena Luisa Rivera y con una tipografía creada por el hijo del autor, Gonzalo García Barcha.<br>Una edición conmemorativa de una novela clave en la historia de la literatura, una obra que todos deberíamos tener en nuestras estanterías.</b><br><br><br>“Muchos años después, frente al pelotón de fusilamiento, el coronel Aureliano Buendía había de recordar aquella tarde remota en que su padre lo llevó a conocer el hielo”.<br><br>Con estas palabras empieza una novela ya legendaria en los anales de la literatura universal, una de las aventuras literarias más fascinantes del siglo xx. Millones de ejemplares de <b>Cien años de soledad</b> leídos en todas las lenguas y el Premio Nobel de Literatura coronando una obra que se había abierto paso a “boca a boca” —como gusta decir el escritor— son la más palpable demostración de que la aventura fabulosa de la familia Buendía-Iguarán, con sus milagros, fantasías, obsesiones, tragedias, incestos, adulterios, rebeldías, descubrimientos y condenas, representaba al mismo tiempo el mito y la historia, la tragedia y el amor del mundo entero.<br><br><b>ENGLISH DESCRIPTION<br><br>Commemorating the 50th anniversary since <i>One Hundred Years of Solitude</i>’s first publication, this edition includes unpublished illustrations by the Chilean artist Luisa Rivera and a typeface created by the author''s son, Gonzalo García Barcha. <br></b> <br><b> A commemorative edition of a fundamental novel in the history of literature, a work that we should all have on our bookshelves. </b><br><br> This novel, now legendary in world literature records, is one of the most fascinating literary adventures of the twentieth century. Millions of copies of <i>One Hundred Years of Solitude</i> have been read in all languages and the Nobel Prize in Literature crowning a work that had made its way through word of mouth, are the most palpable demonstration that the fabulous adventure of the Buendía-Iguarán family, with its miracles, fantasies, obsessions, tragedies, incests, adulteries, rebellions, discoveries, and convictions, represented at the same time the myth and the history, as well as the tragedy and the love of the entire world.', '9780525562443', 400, '2017-10-24', NULL, '2026-02-10T18:28:31.058414+00:00', 'es', 'PRH Grupo Editorial') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('d436283a-8848-4d9d-8abc-03f24def2589', 'La península de las casas vacías', '5398cede-fc48-472b-bece-a9e605def264', 'https://images.isbndb.com/covers/25402043485185.jpg', 'UNA NOVELA TOTAL SOBRE LA GUERRA CIVIL ESPAÑOLA EN CLAVE DE REALISMO MÁGICO<br></br><br></br>Premio Cálamo Libro del Año 2024<br></br>Premio Andalucía de la Crítica<br></br>Candidato español al Premio Literario de la Unión Europea<br></br>Premio Kelvin 505 del Festival Celcius 232 a la mejor novela original en castellano publicada por primera vez en España en 2024<br></br>Premio Espartaco en la Semana Negra de Gijón a la mejor novela histórica escrita en español<br></br> <br></br>He aquí la historia de la descomposición total de una familia, de la deshumanización de un pueblo, de la desintegración de un territorio y de una península de casas vacías.<br></br> <br></br>La historia de un soldado que se raja la piel para dejar salir la ceniza acumulada, de un poeta que cose la sombra de una niña tras un bombardeo, y de un maestro que enseña a sus alumnos a hacerse los muertos; de un general que duerme junto a la mano cortada de una santa, de un niño ciego que recupera la vista durante un apagón, y de una campesina que pinta de negro todos los árboles de su huerto; de un fotógrafo extranjero que pisa una mina cerca de Brunete y no levanta el pie en cuarenta años, de un gernikarra que conduce hasta el centro de París una camioneta con los restos humeantes de un ataque aéreo, y de un perro herido cuya sangre teñirá la última franja de una bandera abandonada en Badajoz.<br></br> <br></br>He aquí pues la historia total de la Guerra Civil española y de una Iberia agonizante donde lo fantástico apuntala la crudeza de lo real; donde los anónimos miembros de un extenso clan de olivareros de Jándula cruzan sus destinos con los de Alberti, Lorca y Unamuno; Rodoreda, Zambrano y Kent; Hemingway, Orwell y Bernanos; Picasso y Mallo; Azaña y Foxá; donde lo épico y lo costumbrista se entrelazan para tejer un portentoso tapiz, poético y grotesco, bello y delirante.<br></br> <br></br>«Es lo mejor que he leído en muchísimos años. David Uclés ha escrito un libro extraordinario que va a quedar en la historia de la literatura de nuestro país».<br></br>Iñaki Gabilondo<br></br> <br></br>«Una familia del sur se abisma en la guerra civil española como en la maldición de un naufragio. David Uclés relata la historia de esta estirpe —espejo de un país entero— con perfecto pulso narrativo y exuberancia, con insólito ingenio, con humor y dolor, con el don de la fantasía alada y la imagen nítida. Advertencia para lectores: incurren en grave riesgo de fascinación».<br></br>Irene Vallejo<br></br> <br></br>«Que la imaginación es quizá la herramienta más reveladora, sólida y hermosa de indagación en la realidad es algo que David Uclés demuestra en cada página de este libro, capaz de encontrar belleza en los paisjes desolados de uno de los episodios más importantes de la historia reciente de Europa, que quizá se haya contado antes, pero nunca así».<br></br>Fernando León de Aranoa<br></br> <br></br>«Ninguna novela contemporánea me ha conmovido tanto como La península de las casas vacías. Estoy asombrado y agradecido».<br></br>Ian Gibson<br></br> <br></br>«Imaginación, historia, buena prosa y creatividad ética. David Uclés logra en La península de las casas vacías el reto literario de que su imaginación sea habitada por los lectores. Consigue que las experiencias individuales conformen una visión global sobre unos de los conflictos más conmovedores de la historia europea contemporánea, y nos hace comprender la vida humana que late bajo los números, los datos y las fechas».<br></br>Luis García Montero<br></br> <br></br>«Con una prosa imprevista, tan original como desacomplejada, David Uclés es un auténtico soplo de aire fresco en las letras españolas».<br></br>Pablo Martín Sánchez<br></br> <br></br>«La honestidad de Uclés impresiona, igual que la convicción con que acomete el desafío».<br></br> Nadal Suau, Babelia, El País<br></br> <br></br>«He aquí un desgarrador libro —como nuestra propia Historia— que es, a un mismo tiempo, crónica familiar y fresco de una guerra de la que todos somos herederos y que todavía hoy, lamentablemente, nos separa». <br></br>Antonio Rojas, AISGE<br></br> <br></br>«Una muy buena novela, valiente y divertida, ocurrente y bien escrita.(…) David Uclés consigue la hazaña narrativa de contar con humor algunos episodios de extrema violencia y no estrellarse».<br></br>Juan Marqués, La Lectura, El Mundo<br></br> <br></br>«Esta novela es un triple salto mortal que le ha salido muy bien al autor: escritura honesta, comprometida, extemporánea (en el buen sentido) y una memoria dignificante».<br></br>Nadal Suau, El País<br></br> <br></br> «David Uclés nos sitúa en una ficción que nos hipnotiza desde la primera página».<br></br>Ahora qué Leo, La Sexta<br></br> <br></br>«Va a ser una obra de gran resonancia. Sus 700 páginas se te hacen cortas». <br></br>Fulgencio Argüelles, El Comercio<br></br> <br></br>«Esta novela no os dejará indiferentes, por lo que cuenta y por cómo lo cuenta. Empiezas a leer y enseguida te atrapa la voz del narrador».<br></br>Página 2, La 2<br></br><br></br>«Los hallazgos literarios de esta novela son múltiples (…), y tiene una galería de personajes difícil de olvidar porque su autor, con suma destreza, le otorga unos dones que les define como únicos. Magnífica».<br></br>Juan Ángel Juristo, La Vanguardia<br></br> <br></br>«Una Guerra Civil contada como nunca: David Uclés es la revelación literaria de la temporada».<br></br>Clara Asín, elnacional.cat<br></br> <br></br>«Es una novela muy bien escrita, con un dominio de la palabra y de las imágenes muy solvente». <br></br>José Ma Pozuelo Yvancos, Abc Cultural<br></br><br></br>«De lo mejor que le ha pasado a la literatura española en los últimos años. La península de las casas vacías es una novela mágica, por su capacidad narrativa, desbordante, y por su ambición de contar la Guerra Civil como nunca se había hecho antes».<br></br>Inés M. Rodrigo, Abril, El Periódico de España<br></br> <br></br>«Es un libro único y extraordinario. Me conmovió toda y me hizo entender y sufrir por la Guerra Civil en España. Personajes inolvidables y una prosa mágica que desafía los límites de la realidad». <br></br>Gioconda Belli', '9788419942319', 700, '2025-09-18', NULL, '2026-02-10T18:29:39.241634+00:00', 'es', 'Siruela') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('845870b0-a0d8-4518-a2b9-44501a950aff', 'Dune', '90c2649c-4cc0-4fa7-aba7-d08f8805ecc6', 'https://images.isbndb.com/covers/6042353482580.jpg', 'Frank Herbert’s classic masterpiece—a triumph of the imagination and one of the bestselling science fiction novels of all time. Set on the desert planet Arrakis, Dune is the story of Paul Atreides—who would become known as Muad''Dib—and of a great family''s ambition to bring to fruition mankind''s most ancient and unattainable dream. A stunning blend of adventure and mysticism, environmentalism and politics, Dune won the first Nebula Award, shared the Hugo Award, and formed the basis of what is undoubtedly the grandest epic in science fiction.', '9781101658055', 896, '2003-08-26', NULL, '2026-02-10T19:00:13.300718+00:00', 'English', 'Penguin US') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('308c86d8-e1d6-4028-804f-64afaf5b689a', 'El conde de Montecristo', 'aab6892c-ab18-4cc7-89ac-9fc270ef9d29', 'https://images.isbndb.com/covers/5268113485185.jpg', 'Thrown in prison for a crime he has not committed, Edmond Dantès is confined to the grim fortress of If. There he learns of a great hoard of treasure hidden on the Isle of Monte Cristo and he becomes determined not only to escape, but also to unearth the treasure and use it to plot the destruction of the three men responsible for his incarceration. Dumas’ epic tale of suffering and retribution, inspired by a real-life case of wrongful imprisonment, was a huge popular success when it was first serialized in the 1840s.<br/><br/>Robin Buss’s lively English translation is complete and unabridged, and remains faithful to the style of Dumas’s original. This edition includes an introduction, explanatory notes and suggestions for further reading.', '9788417928926', 1181, '2020-01-01', NULL, '2026-02-10T19:08:42.635639+00:00', 'es', 'Plutón Ediciones') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('3ecbb16b-01fe-4eeb-80fc-6527308c4a38', 'La montaña mágica / The Magic Mountain (Spanish Edition)', '41d4df58-856a-42df-bd47-385cf88cdb91', 'https://images.isbndb.com/covers/12044483485202.jpg', 'El propio Thomas Mann advierte que esta novela trata sobre «la pasión como desequilibrio y degradación».<br/><br/>Gustav Aschenbach, «arroyo de cenizas» en alemán, es un escritor maduro que goza de reconocimiento. Llega a Venecia en busca de inspiración, pero también de llenar sus días con reflexiones estéticas en un entorno idílico.<br/><br/>En el hotel coincide con Tadzio, un joven de polaco que se encuentra de vacaciones con su familia. El muchacho se convierte en objeto de deseo y adoración; un amor ideal e imposible basado en la contemplación estética y que llevará a Aschenbach a renunciar a todo, incluso a sí mismo. «Hay, entre los resquicios de esa historia, un abismo que ella deja entrever y que inmediatamente identificamos en nosotros mismos.»<br/><br/>ENGLISH DESCRIPTION<br/><br/>Thomas Mann''s novel The Magic Mountain presents a panorama of European society in the first two decades of the 20th century and depicts the philosophical and metaphysical dilemmas facing people in the modern age.<br/><br/>In the years leading up to the First World War, the fundamental elements of human nature were thrown into sharp relief by the political tensions that resulted in the ultimate metaphor for the innate destructiveness of humankind: the War itself. If such a war is the true expression of human tendencies, what hope is there for the future? Through the figure of the main character of the novel, Thomas Mann explores the alternative philosophies of life available to human beings in the modern age, and invites the reader to undertake a personal odyssey of discovery, with a view to adopting a positive approach in an era that seems to offer no clear-cut answers.<br/><br/>This book is a comprehensive commentary on Thomas Mann''s seminal novel, one of the key literary artefacts of the 20th century. The author has taken upon himself the task of explaining all the references and allusions contained in the novel, and of providing readers who know little or no German with enough explanatory comments to enable them to understand the novel and extract the maximum reading pleasure from it.', '9788466352406', 1056, '2020-03-23', NULL, '2026-02-10T19:10:04.90187+00:00', 'es', 'Debolsillo') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('63572464-9e96-4bcb-abfb-8ee99de1c0df', 'Rojo y Negro', 'ac4bca21-9f01-4057-bb9f-ca6e6537e1e0', 'https://images.isbndb.com/covers/5590933485195.jpg', '<p>"Rojo y negro relata el nacimiento, ascensión y caída de un héroe, Julien Sorel, quien, hijo de un humilde carpintero, destaca por su inteligencia e inquietudes intelectuales, y sueña con ascender socialmente y huir del mundo provinciano y rural que le rodea. Pero para lograrlo debe traicionar muchos de sus verdaderos sentimientos, los cuales irán modelando al personaje durante su intensa trayectoria vital: el amor que se convierte en amor propio, la pasión que se torna ambición, la generosidad y el entusiasmo que se desvanecen y la hipocresía, incansable compañera.HenryBayle, Stendhal¸ hace un retrato magistral de la Francia de los inicios del siglo xix que convierte a Rojo y negro en una obra clave de la literatura contemporánea: un Antiguo Régimen que se resiste a morir tras el vuelco que supuso la Revolución francesa, una Iglesia que no quiere perder su influencia, las diferentes corrientes de pensamiento, el intercambio y la mezcla de las clases sociales, la legítima aspiración de las clases populares por ascender en la escala social, los viejos y los nuevos aristócratas… Y Napoleón como fondo, ejemplo y guía de las nuevas generaciones."<br></p>', '9788446046998', 656, '2018-10-15', NULL, '2026-02-10T19:17:56.418759+00:00', 'eng', 'Ediciones Akal') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('a0ef8f36-0fb5-4a5a-91d4-0387800177a6', 'Solenoide', '568d6a63-8c77-4d30-a99d-c679db9c7c86', 'https://images.isbndb.com/covers/25219203485184.jpg', 'Genialidad, locura y grandeza. La última y más madura novela del rumano Mircea Cartarescu, uno de los más poderosos escritores europeos actuales, en una obra que le ha llevado a ser comparado con Pynchon, Kafka y Kundera. Considerada unánimemente por la crítica la obra cumbre de Mircea Cartarescu hasta el momento, Solenoide es una novela monumental en la que resuenan ecos de Pynchon, Borges, Swift y Kafka. Estamos ante el largo diario de un escritor frustrado que desgrana su infancia y su adolescencia en los arrabales de una ciudad comunista, devastada, gris y fría ?una Bucarest alucinada, dotada de una melancolía abrumadora?. Profesor de Rumano en un instituto de barrio, con una carrera literaria fracasada y una profesión que no le interesa, compra una casa antigua con forma de barco, construida por el inventor de un solenoide, que alberga una extraña maquinaria: un sillón de dentista dotado de un tablero de mandos. Pronto íntima con una profesora que ha sido captada por una secta mística, la de los piquetistas, que organizan manifestaciones nocturnas por los cementerios de la ciudad y por la Morgue. Mientras tanto, el narrador se enfrenta a alucinaciones que le revelan la verdad de su existencia. Solenoide es la piedra de toque en torno a la que gravitan el resto de las ficciones de Cartarescu. Una obra que atrae todas las pistas, los temas, las obsesiones literarias de un autor genial que se ha ido convirtiendo, poco a poco, en un escritor de culto.', '9788417115456', 800, '2018-01-01', NULL, '2026-02-10T19:20:46.639044+00:00', 'es', 'Impedimenta') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('8a133e9d-2da6-44ef-b37e-5d56d308f2bc', 'La broma infinita', 'bb209494-c3cd-4b1d-bf35-7b3300f49142', 'https://images.isbndb.com/covers/10415683485214.jpg', '<b>Una novela crítica, divertida y reflexiva sobre la adicción, el consumismo y la soledad de la sociedad norteamericana, escrita con gran sabiduría y sentido del humor.<br></b><br> <b>Un lugar:</b> Enfield, Massachusetts. A cien millas de la Gran Concavidad, un yermo radiactivo lleno de bebés mutantes del tamaño de aviones, criaturas sin cráneo y hordas de hámsters salvajes.<br> <b><br> Una época:</b> el año de la Ropa Interior para Adultos Depend, en el Tiempo Subsidiado, en una América regida por el totalitarismo ecológico de la ONAN, gobernada a su vez por la oscura Oficina de Servicios No Especificados, en guerra perpetua contra el ultraviolento antiONANismo de Quebec.<br> <b>Una institución:</b> la Academia Enfield de Tenis, ultraelitista y donde impera una disciplina destinada a abolir todo placer.<br> <br> <b>Una familia:</b> los Incandenza. James Incandenza, óptico militar convertido en cineasta de <i>après-garde</i>, y su mujer, la promiscua Avril, que alimenta oscuras conexiones con la guerrilla de Quebec. Y sus tres hijos: Orin, genial pateador de fútbol americano y seductor transnacional; Mario, enano y deforme, cineasta como su padre y poseedor de una sensibilidad prodigiosa, y Hal, promesa del tenis juvenil y atormentado por un secreto terrible.<br> <br> <b>Y una película:</b> El <i>samizdat</i>. El Entretenimiento. <i>La broma infinita</i>. Con el poder de enloquecer a todo el que la vea y destruir así la civilización. El arma perfecta por la que todos se enzarzarán en la Guerra Final por el control de América.', '9788499892474', 1212, '2026-03-24', NULL, '2026-02-10T19:23:04.887603+00:00', 'es', 'DEBOLSILLO') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('38d7dffc-971f-4e55-b2f4-c7e7c5790aee', 'Ulises', '3eebb7a9-e499-44d9-b239-f3e371c0d51f', 'https://images.isbndb.com/covers/12120923485202.jpg', '<p> <b>Una de las cumbres de la literatura moderna en una cuidada edición de bolsillo.</b> </p> <p>Irreverente, cómica, erudita, monumental, Ulises es una de las novelas cumbre de la literatura moderna. Su trama sigue las andanzas por Dublín de Stephen Dedalus y Leopold y Molly Bloom a lo largo de un día, el 16 de junio de 1904. Pero tras los detalles cotidianos se oculta un trasfondo mitológico que remite a toda la experiencia humana y enriquece la lectura con infinitos significados. Escrito en una brillante variedad de estilos, el libro ha sido objeto de numerosos estudios, ensayos y controversias, una tradición crítica que la presente edición recoge en su estupenda introducción y en su minucioso aparato de notas.</p> <p> <b>Sobre la obra y el autor:</b> <br> « <i>Ulises </i>no es fácil, pero cada una de sus páginas es maravillosa y compensa el esfuerzo.» <br> Joyce Carol Oates</p> <p>« <i>Ulises</i>, por supuesto, es una obra de arte sublime.» <br> Vladimir Nabokov</p> <p>« <i>Ulises </i>contiene lo que aún está por descubrir de la mente del hombre; es un análisis de la conciencia humana como nunca se había hecho.» <br> Ford Maddox Ford</p> <p>«Joyce continúa despertando pasiones porque su obra -y, en particular, <i>Ulises</i>- es un campo minado donde encontramos nuevas riquezas, nuevos explosivos, cada vez que volvemos.» <br> Edna O''Brien</p> <p>«[ <i>Ulises </i>es] el libro con el que todos estamos en deuda y del que ninguno de nosotros puede escapar.» <br> T. S. Eliot</p> <p>«Para mí, Joyce es el realista por excelencia porque trataba de transmitir la sensación de la experiencia. Y esta le parecía tan ideosincrásica que tuvo que inventar un nuevo lenguaje para hacerlo.» <br> Zadie Smith</p> <p>«Joyce hizo que todo fuese posible; abrió todas las puertas y ventanas.» <br> Anne Enright</p>', '9788466360050', 976, '2021-09-23', NULL, '2026-02-10T21:00:04.365809+00:00', 'es', 'DEBOLS!LLO') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('e1dde7a8-8919-42da-a904-83fd60c50b32', 'Marcel Proust', 'd29c3820-d6ba-4bd2-8a64-163c081065ab', 'https://images.isbndb.com/covers/23948693482294.jpg', 'Reissued with a new preface to commemorate the first publication of <i>À la recherche du temps perdu</i> one hundred years ago,<i> Marcel Proust</i> portrays in abundant detail the extraordinary&#160;life and times of one of the greatest literary voices of the twentieth century.&#160;“An impeccably researched and well-paced narrative that brings vividly and credibly to life not only the writer himself but also the changing world he knew.”—Roger Pearson, <i>New York Times Book Review</i>&#160;“William C. Carter is Proust’s definitive biographer.”—Harold Bloom&#160;&#160;Named a Notable Book of 2000 by the <i>New York Times Book Review</i>', '9780300195095', 1000, '2013-04-16', NULL, '2026-02-10T23:03:25.753931+00:00', 'English', 'Yale University Press') ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('78f15599-67dc-4082-939f-fe11bff70818', 'Inteligencia Artificial. Claves filosóficas para un mundo codificado', 'f28b24b2-4432-40f3-8c84-e568f38b14a7', NULL, NULL, NULL, 420, NULL, NULL, '2026-02-10T23:17:40.061877+00:00', 'es', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.books (id, title, author_id, cover_url, description, isbn, page_count, published_date, genome_data, created_at, language, publisher) VALUES ('4b73b75f-9c9f-4c32-8473-d5307bfe48ff', 'Naná', '0ddb9b96-b904-4b42-aa54-75a5151ea07e', 'https://images.isbndb.com/covers/13897253485211.jpg', 'En el París febril y deslumbrante del Segundo Imperio todo el mundo habla de Naná, la nueva estrella del Teatro de Variedades. Su atractivo es irresistible, su ambición, enorme, pero más allá del brillo de la vida mundana se ocultan también la miseria, el sufrimiento y las tragedias personales. Símbolo de la decadencia de la Francia de su época, Naná es también el prototipo de la mujer fatal y de la cortesana sin escrúpulos sentimentales. Tomado de la contracubierta del libro.', '9788491814894', 517, '2019-01-01', NULL, '2026-02-12T17:50:47.565245+00:00', 'es', 'Alianza Editorial') ON CONFLICT DO NOTHING;
